import os
from typing import Dict, Any, List, Optional
from google.cloud import documentai_v1 as documentai
from document_client import get_documentai_client, get_processor_name
from document_models import DocumentExtractionResult, LineItem

def extract_invoice_fields(image_content: bytes) -> DocumentExtractionResult:
    client, project_id, location = get_documentai_client()
    processor_id = os.environ.get("GOOGLE_CLOUD_DOCUMENTAI_INVOICE_PROCESSOR_ID")

    if not processor_id:
        raise ValueError("GOOGLE_CLOUD_DOCUMENTAI_INVOICE_PROCESSOR_ID environment variable not set.")

    processor_name = get_processor_name(project_id, location, processor_id)

    raw_document = documentai.RawDocument(content=image_content, mime_type="application/pdf")
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)

    result = client.process_document(request=request)
    document = result.document

    vendor_name: Optional[str] = None
    document_date: Optional[str] = None
    total_amount: Optional[float] = None
    line_items: List[LineItem] = []

    for entity in document.entities:
        if entity.type == "vendor_name":
            vendor_name = entity.mention_text
        elif entity.type == "document_date":
            document_date = entity.mention_text
        elif entity.type == "total_amount":
            try:
                total_amount = float(entity.mention_text)
            except (ValueError, TypeError):
                total_amount = None
        elif entity.type == "line_item":
            description: Optional[str] = None
            quantity: Optional[float] = None
            unit_price: Optional[float] = None
            total_price: Optional[float] = None
            for prop in entity.properties:
                if prop.type == "description":
                    description = prop.mention_text
                elif prop.type == "quantity":
                    try:
                        quantity = float(prop.mention_text)
                    except (ValueError, TypeError):
                        quantity = None
                elif prop.type == "unit_price":
                    try:
                        unit_price = float(prop.mention_text)
                    except (ValueError, TypeError):
                        unit_price = None
                elif prop.type == "amount": # Document AI often uses 'amount' for line item total
                    try:
                        total_price = float(prop.mention_text)
                    except (ValueError, TypeError):
                        total_price = None
            line_items.append(LineItem(description=description, quantity=quantity, unit_price=unit_price, total_price=total_price))

    return DocumentExtractionResult(
        vendor_name=vendor_name,
        document_date=document_date,
        total_amount=total_amount,
        line_items=line_items,
        raw_response=document.to_dict() # Convert Document object to dictionary for raw_response
    )

import os
from typing import Dict, Any, List, Optional
import boto3
from document_models import DocumentExtractionResult, LineItem

def extract_receipt_fields(image_content: bytes) -> DocumentExtractionResult:
    client = boto3.client('textract', region_name=os.environ.get("AWS_REGION"))

    response = client.analyze_expense(Document={'Bytes': image_content})

    merchant_name: Optional[str] = None
    tax_amount: Optional[float] = None
    total_amount: Optional[float] = None
    line_items: List[LineItem] = []

    if response.get('ExpenseDocuments'):
        expense_document = response['ExpenseDocuments'][0]

        # Extract summary fields
        for summary_field in expense_document.get('SummaryFields', []):
            if summary_field.get('Type', {}).get('Text') == 'VENDOR_NAME':
                merchant_name = summary_field.get('ValueDetection', {}).get('Text')
            elif summary_field.get('Type', {}).get('Text') == 'TOTAL':
                try:
                    total_amount = float(summary_field.get('ValueDetection', {}).get('Text'))
                except (ValueError, TypeError):
                    total_amount = None
            elif summary_field.get('Type', {}).get('Text') == 'TAX':
                try:
                    tax_amount = float(summary_field.get('ValueDetection', {}).get('Text'))
                except (ValueError, TypeError):
                    tax_amount = None

        # Extract line items
        for line_item_group in expense_document.get('LineItemGroups', []):
            for item in line_item_group.get('LineItems', []):
                description: Optional[str] = None
                quantity: Optional[float] = None
                price: Optional[float] = None
                total_price: Optional[float] = None

                for field in item.get('LineItemExpenseFields', []):
                    if field.get('Type', {}).get('Text') == 'ITEM':
                        description = field.get('ValueDetection', {}).get('Text')
                    elif field.get('Type', {}).get('Text') == 'QUANTITY':
                        try:
                            quantity = float(field.get('ValueDetection', {}).get('Text'))
                        except (ValueError, TypeError):
                            quantity = None
                    elif field.get('Type', {}).get('Text') == 'PRICE':
                        try:
                            price = float(field.get('ValueDetection', {}).get('Text'))
                        except (ValueError, TypeError):
                            price = None
                    elif field.get('Type', {}).get('Text') == 'TOTAL':
                        try:
                            total_price = float(field.get('ValueDetection', {}).get('Text'))
                        except (ValueError, TypeError):
                            total_price = None
                line_items.append(LineItem(description=description, quantity=quantity, unit_price=price, total_price=total_price))

    # For receipts, we can map merchant_name to vendor_name for consistency with DocumentExtractionResult
    return DocumentExtractionResult(
        vendor_name=merchant_name,
        total_amount=total_amount,
        line_items=line_items,
        raw_response=response
    )

from typing import List
from document_models import ExpenseNormalizationSchema

def validate_document_fields(expense_record: ExpenseNormalizationSchema, required_fields: List[str], min_confidence: float = 0.7) -> ExpenseNormalizationSchema:
    validation_errors = []

    for field in required_fields:
        field_value = getattr(expense_record, field, None)
        if field_value is None:
            validation_errors.append(f"Missing required field: {field}")

        # Check confidence score if available for the field
        if field in expense_record.confidence_scores:
            if expense_record.confidence_scores[field] < min_confidence:
                validation_errors.append(f"Low confidence for field {field}: {expense_record.confidence_scores[field]:.2f} (min {min_confidence:.2f})")

    if validation_errors:
        expense_record.validation_status = f"failed: {'; '.join(validation_errors)}"
    else:
        expense_record.validation_status = "validated"

    return expense_record

import os
from typing import Dict, Any
from openai import OpenAI
from document_models import DocumentExtractionResult

def summarize_invoice_fields(extracted_data: DocumentExtractionResult) -> str:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))

    vendor_name = extracted_data.vendor_name or "N/A"
    document_date = extracted_data.document_date or "N/A"
    total_amount = extracted_data.total_amount or "N/A"
    line_items_summary = "No line items found." if not extracted_data.line_items else \
                         "\n".join([f"- {item.description or 'Item'}: {item.total_price or 'N/A'}" for item in extracted_data.line_items])

    prompt = f"""Summarize the following invoice details:
    Vendor: {vendor_name}
    Date: {document_date}
    Total Amount: {total_amount}
    Line Items:
    {line_items_summary}

    Provide a concise summary in one paragraph."""

    response = client.chat.completions.create(
        model="gpt-4o-mini",  # Using a concrete model identifier
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes invoice details."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=150
    )

    return response.choices[0].message.content.strip()
